479	// provisionContext creates a new context from the given configuration and provisions
480	// storage and apps.
481	// If `newCfg` is nil a new empty configuration will be created.
482	// If `replaceAdminServer` is true any currently active admin server will be replaced
483	// with a new admin server based on the provided configuration.
484	func provisionContext(newCfg *Config, replaceAdminServer bool) (Context, error) {
485		// because we will need to roll back any state
486		// modifications if this function errors, we
487		// keep a single error value and scope all
488		// sub-operations to their own functions to
489		// ensure this error value does not get
490		// overridden or missed when it should have
491		// been set by a short assignment
492		var err error
493	
494		if newCfg == nil {
495			newCfg = new(Config)
496		}
497	
498		// create a context within which to load
499		// modules - essentially our new config's
500		// execution environment; be sure that
501		// cleanup occurs when we return if there
502		// was an error; if no error, it will get
503		// cleaned up on next config cycle
504		ctx, cancelCause := NewContextWithCause(Context{Context: context.Background(), cfg: newCfg})
505		defer func() {
506			if err != nil {
507				globalMetrics.configSuccess.Set(0)
508				// if there were any errors during startup,
509				// we should cancel the new context we created
510				// since the associated config won't be used;
511				// this will cause all modules that were newly
512				// provisioned to clean themselves up
513				cancelCause(fmt.Errorf("configuration error: %w", err))
514	
515				// also undo any other state changes we made
516				if currentCtx.cfg != nil {
517					certmagic.Default.Storage = currentCtx.cfg.storage
518				}
519			}
520		}()
521		newCfg.cancelFunc = cancelCause // clean up later
522	
523		// set up logging before anything bad happens
524		if newCfg.Logging == nil {
525			newCfg.Logging = new(Logging)
526		}
527		err = newCfg.Logging.openLogs(ctx)
528		if err != nil {
529			return ctx, err
530		}
531	
532		// create the new filesystem map
533		newCfg.fileSystems = &filesystems.FileSystemMap{}
534	
535		// prepare the new config for use
536		newCfg.apps = make(map[string]App)
537		newCfg.failedApps = make(map[string]error)
538	
539		// set up global storage and make it CertMagic's default storage, too
540		err = func() error {
541			if newCfg.StorageRaw != nil {
542				val, err := ctx.LoadModule(newCfg, "StorageRaw")
543				if err != nil {
544					return fmt.Errorf("loading storage module: %v", err)
545				}
546				stor, err := val.(StorageConverter).CertMagicStorage()
547				if err != nil {
548					return fmt.Errorf("creating storage value: %v", err)
549				}
550				newCfg.storage = stor
551			}
552	
553			if newCfg.storage == nil {
554				newCfg.storage = DefaultStorage
555			}
556			certmagic.Default.Storage = newCfg.storage
557	
558			return nil
559		}()
560		if err != nil {
561			return ctx, err
562		}
563	
564		// start the admin endpoint (and stop any prior one)
565		if replaceAdminServer {
566			err = replaceLocalAdminServer(newCfg, ctx)
567			if err != nil {
568				return ctx, fmt.Errorf("starting caddy administration endpoint: %v", err)
569			}
570		}
571	
572		// Load and Provision each app and their submodules
573		err = func() error {
574			for appName := range newCfg.AppsRaw {
575				if _, err := ctx.App(appName); err != nil {
576					return err
577				}
578			}
579			return nil
580		}()
581		return ctx, err
582	}
583	
584	// ProvisionContext creates a new context from the configuration and provisions storage
585	// and app modules.
586	// The function is intended for testing and advanced use cases only, typically `Run` should be
587	// use to ensure a fully functional caddy instance.
588	// EXPERIMENTAL: While this is public the interface and implementation details of this function may change.
589	func ProvisionContext(newCfg *Config) (Context, error) {
590		return provisionContext(newCfg, false)
591	}
592	
593	// finishSettingUp should be run after all apps have successfully started.
594	func finishSettingUp(ctx Context, cfg *Config) error {
595		// establish this server's identity (only after apps are loaded
596		// so that cert management of this endpoint doesn't prevent user's
597		// servers from starting which likely also use HTTP/HTTPS ports;
598		// but before remote management which may depend on these creds)
599		err := manageIdentity(ctx, cfg)
600		if err != nil {
601			return fmt.Errorf("provisioning remote admin endpoint: %v", err)
602		}
603	
604		// replace any remote admin endpoint
605		err = replaceRemoteAdminServer(ctx, cfg)
606		if err != nil {
607			return fmt.Errorf("provisioning remote admin endpoint: %v", err)
608		}
609	
610		// if dynamic config is requested, set that up and run it
611		if cfg != nil && cfg.Admin != nil && cfg.Admin.Config != nil && cfg.Admin.Config.LoadRaw != nil {
612			val, err := ctx.LoadModule(cfg.Admin.Config, "LoadRaw")
613			if err != nil {
614				return fmt.Errorf("loading config loader module: %s", err)
615			}
616	
617			logger := Log().Named("config_loader").With(
618				zap.String("module", val.(Module).CaddyModule().ID.Name()),
619				zap.Int("load_delay", int(cfg.Admin.Config.LoadDelay)))
620	
621			runLoadedConfig := func(config []byte) error {
622				logger.Info("applying dynamically-loaded config")
623				err := changeConfig(http.MethodPost, "/"+rawConfigKey, config, "", false)
624				if errors.Is(err, errSameConfig) {
625					return err
626				}
627				if err != nil {
628					logger.Error("failed to run dynamically-loaded config", zap.Error(err))
629					return err
630				}
631				logger.Info("successfully applied dynamically-loaded config")
632				return nil
633			}
634	
635			if cfg.Admin.Config.LoadDelay > 0 {
636				go func() {
637					// the loop is here to iterate ONLY if there is an error, a no-op config load,
638					// or an unchanged config; in which case we simply wait the delay and try again
639					for {
640						timer := time.NewTimer(time.Duration(cfg.Admin.Config.LoadDelay))
641						select {
642						case <-timer.C:
643							loadedConfig, err := val.(ConfigLoader).LoadConfig(ctx)
644							if err != nil {
645								logger.Error("failed loading dynamic config; will retry", zap.Error(err))
646								continue
647							}
648							if loadedConfig == nil {
649								logger.Info("dynamically-loaded config was nil; will retry")
650								continue
651							}
652							err = runLoadedConfig(loadedConfig)
653							if errors.Is(err, errSameConfig) {
654								logger.Info("dynamically-loaded config was unchanged; will retry")
655								continue
656							}
657						case <-ctx.Done():
658							if !timer.Stop() {
659								<-timer.C
660							}
661							logger.Info("stopping dynamic config loading")
662						}
663						break
664					}
665				}()
666			} else {
667				// if no LoadDelay is provided, will load config synchronously
668				loadedConfig, err := val.(ConfigLoader).LoadConfig(ctx)
669				if err != nil {
670					return fmt.Errorf("loading dynamic config from %T: %v", val, err)
671				}
672				// do this in a goroutine so current config can finish being loaded; otherwise deadlock
673				go func() { _ = runLoadedConfig(loadedConfig) }()
674			}
675		}
676	
677		return nil
678	}
679	
680	// ConfigLoader is a type that can load a Caddy config. If
681	// the return value is non-nil, it must be valid Caddy JSON;
682	// if nil or with non-nil error, it is considered to be a
683	// no-op load and may be retried later.
684	type ConfigLoader interface {
685		LoadConfig(Context) ([]byte, error)
686	}
687	
688	// Stop stops running the current configuration.
689	// It is the antithesis of Run(). This function
690	// will log any errors that occur during the
691	// stopping of individual apps and continue to
692	// stop the others. Stop should only be called
693	// if not replacing with a new config.
694	func Stop() error {
695		currentCtxMu.RLock()
696		ctx := currentCtx
697		currentCtxMu.RUnlock()
698	
699		rawCfgMu.Lock()
700		unsyncedStop(ctx)
701	
702		currentCtxMu.Lock()
703		currentCtx = Context{}
704		currentCtxMu.Unlock()
705	
706		rawCfgJSON = nil
707		rawCfgIndex = nil
708		rawCfg[rawConfigKey] = nil
709		rawCfgMu.Unlock()
710	
711		return nil
712	}
713	
714	// unsyncedStop stops ctx from running, but has
715	// no locking around ctx. It is a no-op if ctx has a
716	// nil cfg. If any app returns an error when stopping,
717	// it is logged and the function continues stopping
718	// the next app. This function assumes all apps in
719	// ctx were successfully started first.
720	//
721	// A lock on rawCfgMu is required, even though this
722	// function does not access rawCfg, that lock
723	// synchronizes the stop/start of apps.
724	func unsyncedStop(ctx Context) {
725		if ctx.cfg == nil {
726			return
727		}
728	
729		// TODO: This event is experimental and subject to change.

