// watchConfigLoader pulls a config from loader every delay and applies it
// with apply, replacing the running config. Pull and apply failures are
// logged and retried on the next tick, so a later valid config can still
// be applied; the running config is left untouched in the meantime. A
// config identical to the running one is a no-op. The loop stops once a
// new config has been applied successfully (if that config also pulls
// dynamically, its own watcher takes over) or when ctx is canceled; a
// pull that returns after cancellation is discarded.
func watchConfigLoader(ctx Context, loader ConfigLoader, apply func([]byte) error, delay time.Duration, logger *zap.Logger) {
	for {
		timer := time.NewTimer(delay)
		select {
		case <-timer.C:
		case <-ctx.Done():
			timer.Stop()
			logger.Info("stopping dynamic config loading")
			return
		}

		loadedConfig, err := loader.LoadConfig(ctx)
		if err != nil {
			logger.Error("failed loading dynamic config; will retry", zap.String("phase", "pull"), zap.Error(err))
			continue
		}
		if ctx.Err() != nil {
			// the config was canceled while we were pulling; a late
			// result must not overwrite the running config
			logger.Info("stopping dynamic config loading")
			return
		}
		if loadedConfig == nil {
			logger.Info("dynamically-loaded config was nil; will retry")
			continue
		}
		err = apply(loadedConfig)
		if errors.Is(err, errSameConfig) {
			logger.Info("dynamically-loaded config was unchanged; will retry")
			continue
		}
		if err != nil {
			logger.Error("failed to apply dynamically-loaded config; will retry", zap.String("phase", "apply"), zap.Error(err))
			continue
		}
		// the new config was applied; if it is also configured to pull
		// its own config, the watcher started with it takes over from here
		return
	}
}
