func runWatcher(ctx Context, loader ConfigLoader, apply func([]byte) error) <-chan struct{} {
	done := make(chan struct{})
	go func() {
		watchConfigLoader(ctx, loader, apply, time.Millisecond, zap.NewNop())
		close(done)
	}()
	return done
