func TestWatchConfigLoader_PullFailureThenSuccess(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	cctx := Context{Context: ctx}

	var pulls atomic.Int32
	loader := fakeConfigLoader{loadConfig: func(Context) ([]byte, error) {
		if pulls.Add(1) < 3 {
			return nil, fmt.Errorf("pull failed")
		}
		return []byte(`{"apps":{}}`), nil
	}}

	applied := make(chan []byte, 1)
	done := runWatcher(cctx, loader, func(cfg []byte) error {
		applied <- cfg
		return nil
	})

	select {
	case cfg := <-applied:
		if string(cfg) != `{"apps":{}}` { t.Errorf(...) }
	case <-time.After(5 * time.Second):
		t.Fatal("timed out waiting for config to be applied")
	}
	// watcher must stop after a successful apply
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("watcher did not stop after successful apply")
	}
	if n := pulls.Load(); n < 3 {
		t.Errorf("expected at least 3 pulls, got %d", n)
	}
}
