	// positive load_delay must be rejected to prevent a tight loop
	recursiveConfig := []byte(`{"admin":{"config":{"load":{"module":"http"}}}}`)
	err = changeConfig(http.MethodPost, "/"+rawConfigKey, recursiveConfig, "", false, false)
